public boolean equals(Object o) {
	if (!(o instanceof Point)) return false;
	Point p = (Point) o;
	return x == p.x && y == p.y;
}

// the missing half of the contract: equal objects, equal hash codes
@Override
public int hashCode() {
	return 31 * x + y;
}

